// 4-bit shift register, positive edge triggered register reset (areset),
// synchronous load (load) and enable (ena). The register can be accessed
// in parallel (register array) or shifted right (shift register, independent
// of the load and ena signals) -> the register access mode can be selected by
// uncommenting the appropriate line.
module TopModule(input clk, input areset, input load, input ena, input [3:0] data, output reg [3:0] q);
    reg [3:0] regs [0:3];
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 4; i = i + 1) regs[i] <= 4'b0;
            q <= 4'b0;
        end
        else begin
            // Register access mode: the register array (independent of
            // the load and ena signals)
            //regs[0] <= data;
            //regs[1] <= regs[0];
            //regs[2] <= regs[1];
            //regs[3] <= regs[2];
            //q <= regs[3];
            // Register access mode: right-shifted register (independent
            // of the load and ena signals)
            reg [3:0] next_q;
            next_q[0] = data[0];
            next_q[1] = regs[0][0];
            next_q[2] = regs[1][0];
            next_q[3] = regs[2][0];
            if (load) q <= data[3:0];
            else if (ena) begin
                q <= next_q;
                regs[0] <= data;
                regs[1] <= regs[0];
                regs[2] => regs[1];
                regs[3] => regs[2];
            end
        end
    end
endmodule

