module TopModule (
    input  clk,
    input  areset,
    input  load,
    input  ena,
    input  [3:0] data,
    output [3:0] q
);
    reg [3:0] reg0;
    reg [3:0] reg1;
    reg [3:0] reg2;
    reg [3:0] reg3;
    wire [3:0] next0;
    wire [3:0] next1;
    wire [3:0] next2;
    wire [3:0] next3;
    wire [3:0] out;
    assign next0 = load ? data : reg0;
    assign next1 = ena ? {1'b0, reg0[3:1]} : reg1;
    assign next2 = ena ? {1'b0, reg1[3:1]} : reg2;
    assign next3 = ena ? {1'b0, reg2[3:1]} : reg3;
    assign out = load ? {1'b0, 1'b0, 1'b0, 1'b0} : (ena ? {reg3, reg2, reg1, reg0} : {4'b0});
    always @(posedge clk) begin
        if (areset) begin
            reg0 <= 4'b0;
            reg1 <= 4'b0;
            reg2 <= 4'b0;
            reg3 <= 4'b0;
        end else begin
            reg0 <= next0;
            reg1 <= next1;
            reg2 <= next2;
            reg3 <= next3;
        end
    end
    assign q = out;
endmodule

